// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IOracle {
    function requestInference(bytes32 modelId, bytes calldata input, address callback) external returns (uint256 requestId);
}

struct InferenceRequest {
    address requester;
    bytes32 modelId;
    uint256 timestamp;
    bool fulfilled;
    uint256 resultSlot;
    bool cancelled;
}

struct ModelConfig {
    bytes32 modelHash;
    uint256 maxGas;
    uint256 timeout;
    bool active;
}

contract MLInferenceServer is Ownable, ReentrancyGuard {
    IOracle public oracle;

    mapping(uint256 => InferenceRequest) public requests;
    mapping(bytes32 => ModelConfig) public models;
    mapping(uint256 => bytes) public results;

    uint256 public requestCounter;
    uint256 public configVersion;

    // Environment-dependent: different oracle addresses per chain
    mapping(uint256 => address) public chainOracles;

    event InferenceRequested(uint256 indexed requestId, bytes32 indexed modelId, address requester);
    event InferenceCompleted(uint256 indexed requestId, bytes result);
    event RequestCancelled(uint256 indexed requestId);

    modifier onlyOracle() {
        require(msg.sender == address(oracle), "Only oracle");
        _;
    }

    constructor(address _oracle) {
        oracle = IOracle(_oracle);
        chainOracles[block.chainid] = _oracle;
        configVersion = 1;
    }

    function registerModel(bytes32 modelId, bytes32 modelHash, uint256 maxGas, uint256 timeout) external onlyOwner {
        models[modelId] = ModelConfig({
            modelHash: modelHash,
            maxGas: maxGas,
            timeout: timeout,
            active: true
        });
    }

    function requestInference(bytes32 modelId, bytes calldata input) external nonReentrant returns (uint256) {
        ModelConfig memory config = models[modelId];
        require(config.active, "Model not active");

        uint256 requestId = ++requestCounter;

        requests[requestId] = InferenceRequest({
            requester: msg.sender,
            modelId: modelId,
            timestamp: block.timestamp,
            fulfilled: false,
            resultSlot: requestId,
            cancelled: false
        });

        oracle.requestInference(modelId, input, address(this));

        emit InferenceRequested(requestId, modelId, msg.sender);
        return requestId;
    }

    // Async callback from oracle - safe version checks cancelled flag
    function fulfillInference(uint256 requestId, bytes calldata result) external onlyOracle nonReentrant {
        InferenceRequest storage req = requests[requestId];
        require(!req.fulfilled, "Already fulfilled");
        require(!req.cancelled, "Request cancelled");
        require(req.requester != address(0), "Invalid request");

        // Store result using the resultSlot as key
        results[req.resultSlot] = result;
        req.fulfilled = true;

        emit InferenceCompleted(requestId, result);

        // Notify requester via callback
        _notifyRequester(req.requester, requestId, result);
    }

    function cancelRequest(uint256 requestId) external {
        InferenceRequest storage req = requests[requestId];
        require(msg.sender == req.requester, "Not requester");
        require(!req.fulfilled, "Already fulfilled");
        require(block.timestamp > req.timestamp + models[req.modelId].timeout, "Not timed out");

        // Mark as cancelled but preserve the struct for oracle callback rejection
        req.cancelled = true;

        emit RequestCancelled(requestId);
    }

    function updateOracle(address newOracle) external onlyOwner {
        oracle = IOracle(newOracle);
        chainOracles[block.chainid] = newOracle;
        configVersion++;
    }

    function migrateRequests(uint256[] calldata requestIds, uint256 newResultSlot) external onlyOwner {
        for (uint256 i = 0; i < requestIds.length; i++) {
            InferenceRequest storage req = requests[requestIds[i]];
            if (!req.fulfilled && !req.cancelled && req.requester != address(0)) {
                req.resultSlot = newResultSlot + i;
            }
        }
    }

    function getResult(uint256 requestId) external view returns (bytes memory) {
        InferenceRequest memory req = requests[requestId];
        require(req.fulfilled, "Not fulfilled");
        require(!req.cancelled, "Request was cancelled");
        return results[req.resultSlot];
    }

    function _notifyRequester(address requester, uint256 requestId, bytes memory result) internal {
        // Best-effort notification - don't revert if callback fails
        (bool success,) = requester.call(
            abi.encodeWithSignature("onInferenceComplete(uint256,bytes)", requestId, result)
        );
        // Silently ignore failure
    }

    // Batch processing for gas efficiency
    function batchFulfill(uint256[] calldata requestIds, bytes[] calldata resultData) external onlyOracle nonReentrant {
        require(requestIds.length == resultData.length, "Length mismatch");

        for (uint256 i = 0; i < requestIds.length; i++) {
            InferenceRequest storage req = requests[requestIds[i]];
            if (!req.fulfilled && !req.cancelled && req.requester != address(0)) {
                results[req.resultSlot] = resultData[i];
                req.fulfilled = true;
                emit InferenceCompleted(requestIds[i], resultData[i]);
            }
        }
    }
}
